static const size_t emoji_bin_len = sizeof(emoji_bin);

/* Fast O(log N) lookup directly from the embedded binary data. */
static inline const char *emoji_bin_lookup(const char *name, size_t len)
{
  if (emoji_bin_len < sizeof(EmojiBinHeader))
    return NULL;

  const EmojiBinHeader *hdr = (const EmojiBinHeader *)emoji_bin;
  const EmojiBinEntry *entries = (const EmojiBinEntry *)(emoji_bin + sizeof(EmojiBinHeader));
  const char *strings = (const char *)(emoji_bin + sizeof(EmojiBinHeader) + hdr->count * sizeof(EmojiBinEntry));

  size_t low = 0;
  size_t high = hdr->count;

  while (low < high) {
    size_t mid = low + (high - low) / 2;
    const EmojiBinEntry *e = &entries[mid];
    const char *entry_name = strings + e->name_offset;

    size_t min_len = len < e->name_len ? len : e->name_len;
    int cmp = strncmp(name, entry_name, min_len);
    if (cmp == 0) {
      if (len < e->name_len)
        cmp = -1;
      else if (len > e->name_len)
        cmp = 1;
    }

    if (cmp == 0)
      return strings + e->text_offset;
    if (cmp < 0)
      high = mid;
    else
      low = mid + 1;
  }
  return NULL;
}
